<?php require_once __DIR__.'/config/db.php'; $page_title='Shop — MediNova'; $cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll(); $selected=trim($_GET['category']??''); $q=trim($_GET['q']??''); $sql="SELECT p.*,c.name category_name,c.slug category_slug FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.stock>0";$args=[];if($selected){$sql.=' AND c.slug=?';$args[]=$selected;}if($q){$sql.=' AND (p.name LIKE ? OR p.description LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}$sql.=' ORDER BY p.is_featured DESC,p.id DESC';$s=$pdo->prepare($sql);$s->execute($args);$products=$s->fetchAll();require __DIR__.'/includes/store_header.php';?>
<section class="page-hero"><p class="kicker">MEDINOVA PHARMACY</p><h1>Shop <span>care.</span></h1><p>Browse medicines, wellness, skincare, first aid, baby care and personal care. Every product shown here comes from the database — no random internet images.</p></section>
<section class="content-section"><form class="filter-bar" method="get"><a class="<?=!$selected?'active':''?>" href="shop.php">All</a><?php foreach($cats as $c): ?><a class="<?=$selected===$c['slug']?'active':''?>" href="shop.php?category=<?=e($c['slug'])?>"><?=e($c['name'])?></a><?php endforeach; ?><input name="q" value="<?=e($q)?>" placeholder="Search medicine or product..." style="margin-left:auto;min-width:240px;padding:10px 15px;background:#0b0f0c;border:1px solid var(--line);color:#fff;border-radius:30px"></form><div class="shop-grid"><?php foreach($products as $p): ?><article class="shop-card"><a href="product.php?slug=<?=e($p['slug'])?>"><div class="art" style="--glow:rgba(217,255,84,.18)"><?php if($p['image']): ?><img src="<?=BASE_URL?><?=e($p['image'])?>" alt="<?=e($p['name'])?>"><?php else: ?><div class="medicine-art"><i class="pill"></i><i class="pill p2"></i></div><?php endif; ?></div></a><div class="shop-info"><small><?=e($p['category_name']??'Pharmacy')?></small><h3><?=e($p['name'])?></h3><p style="color:#737c74;font-size:12px;min-height:38px"><?=e(mb_strimwidth($p['description']??'',0,80,'…'))?></p><div class="shop-foot"><strong>Rs. <?=number_format((float)$p['price'])?></strong><button class="add-cart" data-id="<?=$p['id']?>">+</button></div></div></article><?php endforeach; ?></div><?php if(!$products): ?><div class="empty-state">No products matched your search.</div><?php endif; ?></section><?php require __DIR__.'/includes/store_footer.php'; ?>
